#include <vector>
#include <algorithm>

class Solution {
public:
    int longestSubarrayRestrictedPairSums(std::vector<int>& nums, int forbidden) {
        if (nums.empty()) return 0;
        int left = 0, max_len = 1;
        for (size_t right = 1; right < nums.size(); ++right) {
            if (nums[right] + nums[right - 1] == forbidden) {
                left = right;
            }
            max_len = std::max(max_len, (int)right - left + 1);
        }
        return max_len;
    }
};

class Solution {
    public int longestSubarrayRestrictedPairSums(int[] nums, int forbidden) {
        if (nums.length == 0) return 0;
        int left = 0, maxLen = 1;
        for (int right = 1; right < nums.length; right++) {
            if (nums[right] + nums[right - 1] == forbidden) {
                left = right;
            }
            maxLen = Math.max(maxLen, right - left + 1);
        }
        return maxLen;
    }
}

function longestSubarrayRestrictedPairSums(nums, forbidden) {
    if (nums.length === 0) return 0;
    let left = 0, maxLen = 1;
    for (let right = 1; right < nums.length; right++) {
        if (nums[right] + nums[right - 1] === forbidden) {
            left = right;
        }
        maxLen = Math.max(maxLen, right - left + 1);
    }
    return maxLen;
}
